/**
 * DungeonDelver service worker.
 *
 * Hand-written rather than generated by Serwist or Workbox. Those bring a build
 * step and a bundler integration, and this project already has to work around
 * an exFAT volume that breaks symlink-dependent tooling; the caching policy
 * here is about forty lines, so the dependency would cost more than it saves.
 *
 * Policy by request type:
 *   navigations      network-first, falling back to cache, then /offline
 *   /_next/static/*  cache-first — content-hashed, so it is immutable
 *   same-origin GET  stale-while-revalidate
 *   everything else  straight to network (never cache API traffic)
 */

const VERSION = "v1";
const SHELL_CACHE = `delver-shell-${VERSION}`;
const RUNTIME_CACHE = `delver-runtime-${VERSION}`;

const SHELL = [
  "/offline",
  "/manifest.webmanifest",
  "/icon-192.png",
  "/icon-512.png",
  "/favicon.svg",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      /* addAll rejects the whole install if any single entry 404s, which would
         leave the app with no worker at all. */
      .then((cache) => Promise.allSettled(SHELL.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((k) => k !== SHELL_CACHE && k !== RUNTIME_CACHE)
            .map((k) => caches.delete(k)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (request.method !== "GET") return;
  if (url.origin !== self.location.origin) return;

  /* Never touch auth or gameplay endpoints. Serving a cached turn would replay
     a scene the player has already moved past. */
  if (url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((res) => {
          const copy = res.clone();
          caches.open(RUNTIME_CACHE).then((c) => c.put(request, copy));
          return res;
        })
        .catch(async () => {
          const cached = await caches.match(request);
          return cached ?? caches.match("/offline");
        }),
    );
    return;
  }

  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ??
          fetch(request).then((res) => {
            const copy = res.clone();
            caches.open(SHELL_CACHE).then((c) => c.put(request, copy));
            return res;
          }),
      ),
    );
    return;
  }

  event.respondWith(
    caches.match(request).then((cached) => {
      const network = fetch(request)
        .then((res) => {
          if (res.ok) {
            const copy = res.clone();
            caches.open(RUNTIME_CACHE).then((c) => c.put(request, copy));
          }
          return res;
        })
        .catch(() => cached);
      return cached ?? network;
    }),
  );
});
